Here is a highly optimized, robust, and enterprise-grade implementation of a custom generic `Stack<T>` in C# backed by a dynamic array. 

It includes automatic growth (doubling when full), automatic shrinking (halving when 25% full to prevent memory leaks), safety checks, and implements `IEnumerable<T>` to support `foreach` loops in proper LIFO (Last-In, First-Out) order.

### Custom Generic Stack Implementation

```csharp
using System;
using System.Collections;
using System.Collections.Generic;

namespace CustomDataStructures
{
    /// <summary>
    /// Represents a variable size last-in-first-out (LIFO) collection of instances of the same arbitrary type.
    /// </summary>
    /// <typeparam name="T">Specifies the type of elements in the stack.</typeparam>
    public class CustomStack<T> : IEnumerable<T>
    {
        private T[] _items;
        private int _size;
        private int _version; // Tracks modifications to prevent illegal state during enumeration
        private const int DefaultCapacity = 4;

        /// <summary>
        /// Gets the number of elements contained in the Stack.
        /// </summary>
        public int Count => _size;

        /// <summary>
        /// Gets the current capacity of the internal array.
        /// </summary>
        public int Capacity => _items.Length;

        /// <summary>
        /// Gets a value indicating whether the Stack is empty.
        /// </summary>
        public bool IsEmpty => _size == 0;

        /// <summary>
        /// Initializes a new instance of the CustomStack class that is empty and has the default initial capacity.
        /// </summary>
        public CustomStack()
        {
            _items = new T[DefaultCapacity];
            _size = 0;
            _version = 0;
        }

        /// <summary>
        /// Initializes a new instance of the CustomStack class that is empty and has the specified initial capacity.
        /// </summary>
        public CustomStack(int capacity)
        {
            if (capacity < 0)
                throw new ArgumentOutOfRangeException(nameof(capacity), "Capacity cannot be negative.");

            _items = new T[capacity];
            _size = 0;
            _version = 0;
        }

        /// <summary>
        /// Inserts an item at the top of the Stack.
        /// </summary>
        public void Push(T item)
        {
            if (_size == _items.Length)
            {
                // Double the capacity (handle initial 0-capacity edge-case)
                int newCapacity = _items.Length == 0 ? DefaultCapacity : _items.Length * 2;
                Resize(newCapacity);
            }

            _items[_size] = item;
            _size++;
            _version++;
        }

        /// <summary>
        /// Removes and returns the object at the top of the Stack.
        /// </summary>
        public T Pop()
        {
            if (IsEmpty)
                throw new InvalidOperationException("Stack is empty. Cannot pop an item.");

            _size--;
            T poppedItem = _items[_size];

            // Clean up the reference to allow Garbage Collector to reclaim memory (crucial for reference types)
            _items[_size] = default!; 
            _version++;

            // Shrink the array if the size drops below 25% of the capacity
            // This prevents the stack from consuming unnecessary memory
            if (_size > 0 && _size <= _items.Length / 4 && _items.Length / 2 >= DefaultCapacity)
            {
                Resize(_items.Length / 2);
            }

            return poppedItem;
        }

        /// <summary>
        /// Returns the object at the top of the Stack without removing it.
        /// </summary>
        public T Peek()
        {
            if (IsEmpty)
                throw new InvalidOperationException("Stack is empty. Cannot peek.");

            return _items[_size - 1];
        }

        /// <summary>
        /// Removes all objects from the Stack.
        /// </summary>
        public void Clear()
        {
            // Clear references so GC can collect them
            Array.Clear(_items, 0, _size);
            _size = 0;
            _version++;
        }

        /// <summary>
        /// Resizes the backing array to a new capacity.
        /// </summary>
        private void Resize(int newCapacity)
        {
            T[] destinationArray = new T[newCapacity];
            if (_size > 0)
            {
                Array.Copy(_items, destinationArray, _size);
            }
            _items = destinationArray;
        }

        /// <summary>
        /// Returns an enumerator that iterates through the Stack in LIFO order.
        /// </summary>
        public IEnumerator<T> GetEnumerator()
        {
            int originalVersion = _version;

            // Iterate from the top of the stack (last element) down to the bottom
            for (int i = _size - 1; i >= 0; i--)
            {
                // If the collection was modified during iteration, throw an exception
                if (originalVersion != _version)
                {
                    throw new InvalidOperationException("Collection was modified; enumeration operation may not execute.");
                }
                yield return _items[i];
            }
        }

        IEnumerator IEnumerable.GetEnumerator()
        {
            return GetEnumerator();
        }
    }
}
```

